import type { IconShape, IconThemeName } from "./placement";
import { themeByName } from "./placement";

/**
 * The local IconPark icon set.
 *
 * The set is a sibling file, `icons/iconpark.json`, generated by `scripts/build-iconpark.mjs`. It is
 * not embedded in `main.js` because the full set is ~1.2 MB and Obsidian would parse that on every
 * plugin load; here it is read once, on first use, and only if the user ever picks an icon.
 *
 * Two properties of IconPark make the themes cheap:
 *
 * - An icon is **one static template** painted from a four-slot palette. `outline` / `filled` /
 *   `two-tone` / `multi-color` are four colour *mappings* over that template, not four drawings, so
 *   the theme costs nothing to store and nothing to bundle.
 * - The stored markup keeps the sentinel colours `C0..C3` the generator wrote, and a theme is
 *   applied by substituting real colours for them. So a single stored icon serves all four themes.
 */

/** One icon as stored: a template still carrying its `C0..C3` palette sentinels. */
export interface StoredIcon {
  readonly viewBox: string;
  readonly body: string;
}

export interface IconSetMeta {
  readonly source: string;
  readonly package: string;
  readonly license: string;
  readonly viewBox: string;
  readonly stroke: number;
  readonly strokeLinecap: string;
  readonly strokeLinejoin: string;
  readonly themes: readonly string[];
  readonly count: number;
  readonly icons: Readonly<Record<string, StoredIcon>>;
}

export const ICON_SET_PATH = "icons/iconpark.json";

/** File-backed set, loaded at most once per session. */
let cached: IconSetMeta | null = null;
let pending: Promise<IconSetMeta> | null = null;

/** Injected loader, so tests can supply a set without touching the filesystem. */
export type IconSetLoader = () => Promise<IconSetMeta>;

export function setIconSetLoader(loader: IconSetLoader | null): void {
  cached = null;
  pending = null;
  defaultLoader = loader;
}

let defaultLoader: IconSetLoader | null = null;

export async function loadIconSet(loader?: IconSetLoader): Promise<IconSetMeta> {
  if (cached) return cached;
  const load = loader ?? defaultLoader;
  if (!load) throw new Error("Auto Icon: no icon-set loader configured");

  // Concurrent callers must share one read, not each start their own.
  if (!pending) {
    pending = load()
      .then((set) => {
        cached = set;
        return set;
      })
      .finally(() => {
        pending = null;
      });
  }
  return pending;
}

/** Synchronous view of an already-loaded set, or `null` before the first load. */
export function loadedIconSet(): IconSetMeta | null {
  return cached;
}

export function iconNames(set: IconSetMeta): string[] {
  return Object.keys(set.icons).sort();
}

export function hasIcon(set: IconSetMeta, icon: string): boolean {
  return Object.prototype.hasOwnProperty.call(set.icons, icon);
}

export function storedIcon(set: IconSetMeta, icon: string): StoredIcon | null {
  return set.icons[icon] ?? null;
}

/** Apply a theme's colours to a stored template. */
export function shapeFor(
  set: IconSetMeta,
  icon: string,
  theme: IconThemeName | string,
  accent?: string
): IconShape | null {
  const stored = storedIcon(set, icon);
  if (!stored) return null;

  const body = stored.body.replace(/C([0-3])/g, (_match, slot: string) => {
    const colour = themeByName(theme, accent).colors[Number(slot) as 0 | 1 | 2 | 3];
    return colour ?? "currentColor";
  });

  // The hoisted stroke attributes belong to the icon, not to a particular theme, so they travel
  // with the shape onto the root <svg>.
  return {
    viewBox: stored.viewBox,
    body,
    stroke: set.stroke,
    strokeLinecap: set.strokeLinecap,
    strokeLinejoin: set.strokeLinejoin,
  };
}